    let active = true;
    const loadCompletion = async (): Promise<void> => {
      try {
        const result = await getSighting(initialCompletionId);
        if (!active) {
          return;
        }

        if (result.ok) {
          setSavedSighting(result.sighting);
          return;
        }

        setErrorMessage(result.message);
      } catch {
        if (active) {
          setErrorMessage(RECENT_SIGHTINGS_FAILURE_MESSAGE);
        }
      }
